16	package org.springframework.samples.petclinic.model;
17	
18	import java.util.Map;
19	
20	/**
21	 * Pure derivations of an {@link Owner}'s read-only attributes.
22	 *
23	 * <p>Each method computes one derived value from an owner's own field values and
24	 * nothing else, so the computations stay stateless and side-effect free. {@link Owner}
25	 * exposes these through thin {@code @Transient} getters that pass in the relevant
26	 * fields; keeping the arithmetic here rather than on the entity leaves {@code Owner}
27	 * to describe its persistent state and relationships while its growing family of
28	 * derived attributes lives together in one place.
29	 */
30	final class OwnerDerivations {
31	
32	    /** Fixed city-to-region table used to derive {@link #region}. */
33	    private static final Map<String, String> CITY_REGION = Map.of(
34	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
35	
36	    /** Region -> inclusive 4-digit postcode range {low, high} used to derive
37	     *  {@link #region} in preference to the city. */
38	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
39	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
40	
41	    private OwnerDerivations() {
42	    }
43	
44	    /**
45	     * The owner's locality, i.e. the canonical region it belongs to. This is read
46	     * from the region-and-hash {@code customerCode} identity: the region is the
47	     * {@code <REGION>} component that precedes the first {@code '-'} of the assigned
48	     * customer code (e.g. {@code NSW} for {@code NSW-9F86D081}). Until an owner has
49	     * been assigned a customer code (for example while its create request is still
50	     * being validated) this falls back to the region derived directly from its own
51	     * fields (see {@link #region(String, String)}).
52	     *
53	     * @return the canonical region string, or {@code "UNKNOWN"}
54	     */
55	    static String locality(String customerCode, String postcode, String city) {
56	        if (customerCode != null) {
57	            int dash = customerCode.indexOf('-');
58	            if (dash >= 0) {
59	                return customerCode.substring(0, dash);
60	            }
61	        }
62	        return region(postcode, city);
63	    }
64	
65	    /**
66	     * The canonical region derived for an owner from its own fields. The postcode is
67	     * consulted first: when it is present and falls within a known region's inclusive
68	     * 4-digit range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD
69	     * 4000-4099}) that region is returned. Only when the postcode is absent or in no
70	     * known range does this fall back to the fixed city-to-region table
71	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}),
72	     * returning {@code "UNKNOWN"} when the city is not in the table either. This yields
73	     * the same region for the known cities while disambiguating cities that share a name
74	     * via their postcode.
75	     *
76	     * @return the canonical region string, or {@code "UNKNOWN"}
77	     */
78	    static String region(String postcode, String city) {
79	        String byPostcode = regionForPostcode(postcode);
80	        if (byPostcode != null) {
81	            return byPostcode;
82	        }
83	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
84	    }
85	
86	    /**
87	     * The region whose inclusive postcode range contains the given postcode, or
88	     * {@code null} when the postcode is absent, not a four-digit number, or in no
89	     * known range.
90	     */
91	    private static String regionForPostcode(String postcode) {
92	        if (postcode == null || !postcode.matches("\\d{4}")) {
93	            return null;
94	        }
95	        int value = Integer.parseInt(postcode);
96	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
97	            int[] range = entry.getValue();
98	            if (value >= range[0] && value <= range[1]) {
99	                return entry.getKey();
100	            }
101	        }
102	        return null;
103	    }
104	
105	    /**
106	     * The owner's membership level, a number from 1 to 3 assigned at creation:
107	     * starting at 1, add 1 when an {@code email} is present and add 1 when
108	     * {@code namesakeCount} is 0, capped at 3 (level 4 is reserved for tenure).
109	     *
110	     * @return the membership level, from 1 to 3
111	     */
112	    static int membershipLevel(String email, Integer namesakeCount) {
113	        int level = 1;
114	        if (email != null && !email.isBlank()) {
115	            level++;
116	        }
117	        if (namesakeCount != null && namesakeCount == 0) {
118	            level++;
119	        }
120	        return Math.min(level, 3);
121	    }
122	
123	    /**
124	     * The owner's preferred contact channel: {@code "EMAIL"} when an {@code email}
125	     * is present, otherwise {@code "PHONE"}.
126	     *
127	     * @return {@code "EMAIL"} or {@code "PHONE"}
128	     */
129	    static String contactPreference(String email) {
130	        if (email != null && !email.isBlank()) {
131	            return "EMAIL";
132	        }
133	        return "PHONE";
134	    }
135	
136	    /**
137	     * The Luhn check digit (0-9) computed over the decimal digits contained in the
138	     * given {@code customerCode}. An absent or digit-free customer code yields
139	     * {@code 0}.
140	     *
141	     * @return the Luhn check digit, from 0 to 9
142	     */
143	    static int checkDigit(String customerCode) {
144	        return luhnCheckDigit(customerCode);
145	    }
146	
147	    /**
148	     * The Luhn check digit (0-9) computed over the decimal digits contained in the
149	     * given value, processed right-to-left with every second digit doubled (and
150	     * reduced by 9 when the double exceeds 9). Non-digit characters are ignored, and
151	     * an absent or digit-free value yields {@code 0}.
152	     */
153	    private static int luhnCheckDigit(String value) {
154	        int sum = 0;
155	        boolean doubleDigit = true;
156	        for (int i = (value == null ? 0 : value.length()) - 1; i >= 0; i--) {
157	            char c = value.charAt(i);
158	            if (c < '0' || c > '9') {
159	                continue;
160	            }
161	            int d = c - '0';
162	            if (doubleDigit) {
163	                d *= 2;
164	                if (d > 9) {
165	                    d -= 9;
166	                }
167	            }
168	            sum += d;
169	            doubleDigit = !doubleDigit;
170	        }
171	        return (10 - (sum % 10)) % 10;
172	    }
173	
174	    /**
175	     * The single derived key used for duplicate detection, formed as
176	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
177	     * The telephone is the owner's stored (E.164-normalised) telephone, the email
178	     * is the stored (lower-cased) email or the empty string when absent, and the
179	     * household component is the stored {@code householdId} or the empty string
180	     * when the owner belongs to no household.
181	     *
182	     * @return the owner's identity key
183	     */
184	    static String identityKey(String telephone, String email, String householdId) {
185	        String tel = telephone == null ? "" : telephone;
186	        String mail = email == null ? "" : email;
187	        String household = householdId == null ? "" : householdId;
188	        return tel + "|" + mail + "|" + household;
189	    }
190	}
