16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "telephone")
49	    @NotEmpty
50	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    @Email
55	    private String email;
56	
57	    @Column(name = "postcode")
58	    private String postcode;
59	
60	    @Column(name = "registration_date")
61	    private LocalDate registrationDate;
62	
63	    @Column(name = "customer_code")
64	    private String customerCode;
65	
66	    @Column(name = "household_id")
67	    private String householdId;
68	
69	    @Column(name = "namesake_count")
70	    private Integer namesakeCount;
71	
72	    @Column(name = "membership_number")
73	    private String membershipNumber;
74	
75	    @Column(name = "bulk_signup_warning")
76	    private Boolean bulkSignupWarning;
77	
78	    @Column(name = "household_size")
79	    private Integer householdSize;
80	
81	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
82	    private Set<Pet> pets;
83	
84	    public String getAddress() {
85	        return this.address;
86	    }
87	
88	    public void setAddress(String address) {
89	        this.address = address;
90	    }
91	
92	    public String getCity() {
93	        return this.city;
94	    }
95	
96	    public void setCity(String city) {
97	        this.city = city;
98	    }
99	
100	    /**
101	     * The owner's locality, i.e. the canonical region it belongs to (read from the
102	     * assigned {@link #customerCode} when present, otherwise derived from the owner's
103	     * own fields via {@link #regionForOwner()}). Derived (not persisted); recomputed
104	     * each call. See {@link OwnerDerivations#locality(String, String, String)} for the
105	     * full derivation.
106	     *
107	     * @return the canonical region string, or {@code "UNKNOWN"}
108	     */
109	    @Transient
110	    public String getLocality() {
111	        return OwnerDerivations.locality(this.customerCode, this.postcode, this.city);
112	    }
113	
114	    /**
115	     * The canonical region derived for this owner from its own fields. Recomputed each
116	     * call. See {@link OwnerDerivations#region(String, String)} for the derivation.
117	     *
118	     * @return the canonical region string, or {@code "UNKNOWN"}
119	     */
120	    public String regionForOwner() {
121	        return OwnerDerivations.region(this.postcode, this.city);
122	    }
123	
124	    /**
125	     * The owner's membership level, a number from 1 to 3. Derived (not persisted);
126	     * recomputed from the current fields each call. See
127	     * {@link OwnerDerivations#membershipLevel(String, Integer)} for how it is assigned.
128	     *
129	     * @return the membership level, from 1 to 3
130	     */
131	    @Transient
132	    public Integer getMembershipLevel() {
133	        return OwnerDerivations.membershipLevel(this.email, this.namesakeCount);
134	    }
135	
136	    /**
137	     * The owner's preferred contact channel, {@code "EMAIL"} or {@code "PHONE"}.
138	     * Derived (not persisted); recomputed from the current fields each call. See
139	     * {@link OwnerDerivations#contactPreference(String)}.
140	     *
141	     * @return {@code "EMAIL"} or {@code "PHONE"}
142	     */
143	    @Transient
144	    public String getContactPreference() {
145	        return OwnerDerivations.contactPreference(this.email);
146	    }
147	
148	    public String getTelephone() {
149	        return this.telephone;
150	    }
151	
152	    public void setTelephone(String telephone) {
153	        this.telephone = telephone;
154	    }
155	
156	    public String getEmail() {
157	        return this.email;
158	    }
159	
160	    public void setEmail(String email) {
161	        this.email = email;
162	    }
163	
164	    public String getPostcode() {
165	        return this.postcode;
166	    }
167	
168	    public void setPostcode(String postcode) {
169	        this.postcode = postcode;
170	    }
171	
172	    public LocalDate getRegistrationDate() {
173	        return this.registrationDate;
174	    }
175	
176	    public void setRegistrationDate(LocalDate registrationDate) {
177	        this.registrationDate = registrationDate;
178	    }
179	
180	    public String getCustomerCode() {
181	        return this.customerCode;
182	    }
183	
184	    public void setCustomerCode(String customerCode) {
185	        this.customerCode = customerCode;
186	    }
187	
188	    /**
189	     * The Luhn check digit (0-9) computed over the digits in this owner's
190	     * {@link #customerCode}. Derived (not persisted); recomputed each call. See
191	     * {@link OwnerDerivations#checkDigit(String)}.
192	     *
193	     * @return the Luhn check digit, from 0 to 9
194	     */
195	    @Transient
196	    public Integer getCheckDigit() {
197	        return OwnerDerivations.checkDigit(this.customerCode);
198	    }
199	
200	    public String getHouseholdId() {
201	        return this.householdId;
202	    }
203	
204	    public void setHouseholdId(String householdId) {
205	        this.householdId = householdId;
206	    }
207	
208	    public Integer getNamesakeCount() {
209	        return this.namesakeCount;
210	    }
211	
212	    public void setNamesakeCount(Integer namesakeCount) {
213	        this.namesakeCount = namesakeCount;
214	    }
215	
216	    public String getMembershipNumber() {
217	        return this.membershipNumber;
218	    }
219	
220	    public void setMembershipNumber(String membershipNumber) {
221	        this.membershipNumber = membershipNumber;
222	    }
223	
224	    public Boolean getBulkSignupWarning() {
225	        return this.bulkSignupWarning;
226	    }
227	
228	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
229	        this.bulkSignupWarning = bulkSignupWarning;
230	    }
231	
232	    public Integer getHouseholdSize() {
233	        return this.householdSize;
234	    }
235	
236	    public void setHouseholdSize(Integer householdSize) {
237	        this.householdSize = householdSize;
238	    }
239	
240	    /**
241	     * The derived key used for duplicate detection, combining this owner's normalised
242	     * telephone, email and {@link #householdId}. Two owners are duplicates exactly when
243	     * their whole identity keys are equal, so members of the same household with
244	     * different telephones have different keys. Derived (not persisted); recomputed each
245	     * call. See {@link OwnerDerivations#identityKey(String, String, String)} for the
246	     * exact format.
247	     *
248	     * @return the owner's identity key
249	     */
250	    @Transient
251	    public String getIdentityKey() {
252	        return OwnerDerivations.identityKey(this.telephone, this.email, this.householdId);
253	    }
254	
255	    /**
256	     * A stable, normalised key identifying this owner's household (same last name
257	     * and address). The last name is folded case- and whitespace-insensitively and
258	     * the address is reduced to its canonical form exactly as in
259	     * {@link #sameHouseholdAs(Owner)}, so two owners share a key iff they share a
260	     * household.
261	     *
262	     * @return the household key
263	     */
264	    public String householdKey() {
265	        return normalize(this.getLastName()) + "�" + normalizeAddress(this.address);
266	    }
267	
268	    /**
269	     * Whether this owner belongs to the same household as {@code other}: that is,
270	     * they share the same last name and address. The last name is compared
271	     * case-insensitively with runs of whitespace collapsed to a single space (and
272	     * surrounding whitespace trimmed); the address is compared in its canonical
273	     * normalised form (see {@link #normalizeAddress(String)}).
274	     *
275	     * @param other the owner to compare against
276	     * @return {@code true} if both owners share a household
277	     */
278	    public boolean sameHouseholdAs(Owner other) {
279	        return normalize(this.getLastName()).equals(normalize(other.getLastName()))
280	            && normalizeAddress(this.address).equals(normalizeAddress(other.address));
281	    }
282	
283	    /**
284	     * Normalise a value for case-insensitive, whitespace-insensitive comparison:
285	     * trim, collapse internal runs of whitespace to a single space and lower-case.
286	     */
287	    private static String normalize(String value) {
288	        if (value == null) {
289	            return "";
290	        }
